#include <fstream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <cstdint>
using namespace std;
struct Mat {int w,h; float c[3]; vector<unsigned char> p;};
int main(int argc,char**argv){ifstream in(argv[1],ios::binary);uint32_t nm,nt;in.read((char*)&nm,4);in.read((char*)&nt,4);vector<Mat>ms(nm);for(auto&m:ms){in.read((char*)&m.w,4);in.read((char*)&m.h,4);in.read((char*)m.c,12);m.p.resize(m.w*m.h*3);in.read((char*)m.p.data(),m.p.size());}int W=1100,H=650;vector<float>depth(W*H,1e20);vector<unsigned char>rgb(W*H*3,26);float tr[19];for(int k=0;k<nt;k++){in.read((char*)tr,sizeof tr);Mat&m=ms[(int)tr[0]];float x[3],y[3],q[3];for(int i=0;i<3;i++){float *v=tr+1+i*6;q[i]=1/v[2];x[i]=W*.5+v[0]*q[i]*760;y[i]=H*.5-v[1]*q[i]*760;}float den=(y[1]-y[2])*(x[0]-x[2])+(x[2]-x[1])*(y[0]-y[2]);if(abs(den)<1e-7)continue;int x0=max(0,(int)floor(min({x[0],x[1],x[2]}))),x1=min(W-1,(int)ceil(max({x[0],x[1],x[2]}))),y0=max(0,(int)floor(min({y[0],y[1],y[2]}))),y1=min(H-1,(int)ceil(max({y[0],y[1],y[2]})));for(int yy=y0;yy<=y1;yy++)for(int xx=x0;xx<=x1;xx++){float b[3];b[0]=((y[1]-y[2])*(xx+.5-x[2])+(x[2]-x[1])*(yy+.5-y[2]))/den;b[1]=((y[2]-y[0])*(xx+.5-x[2])+(x[0]-x[2])*(yy+.5-y[2]))/den;b[2]=1-b[0]-b[1];if(min({b[0],b[1],b[2]})<0)continue;float z=1/(b[0]*q[0]+b[1]*q[1]+b[2]*q[2]);int pix=yy*W+xx;if(z>=depth[pix])continue;depth[pix]=z;float u=0,v=0,l=0;for(int i=0;i<3;i++){float *a=tr+1+i*6;float w=b[i]*q[i]*z;u+=w*a[3];v+=w*a[4];l+=w*a[5];}int tx=min(m.w-1,(int)((u-floor(u))*m.w)),ty=min(m.h-1,(int)((v-floor(v))*m.h));for(int c=0;c<3;c++){float s=m.p[(ty*m.w+tx)*3+c]/255.f;float linear=s<=.04045?s/12.92:pow((s+.055)/1.055,2.4);linear*=m.c[c]*l;float val=linear<=.0031308?linear*12.92:1.055*pow(linear,1/2.4)-.055;rgb[pix*3+c]=(unsigned char)min(255.f,max(0.f,val*255));}}}ofstream out(argv[2],ios::binary);out<<"P6\n"<<W<<" "<<H<<"\n255\n";out.write((char*)rgb.data(),rgb.size());}
